// ============ TAB 2: TICKET PERFECTO Y RENTABILIDAD ============
function TicketPerfecto({ servers, unidadesNegocio, selectedUnidad, setSelectedUnidad, selectedServer, setSelectedServer, selectedSucursal, setSelectedSucursal, sucursales, showSucursalSelector, loadingUnidades }) {
  const [loading, setLoading] = useState(false);
  const [ticketData, setTicketData] = useState(null);
  const [rentabilidad, setRentabilidad] = useState([]);
  const [sourceStatus, setSourceStatus] = useState(null);
  const [sourceMessage, setSourceMessage] = useState('');
  const [cacheUsed, setCacheUsed] = useState(false);
  const [lastSuccessfulSync, setLastSuccessfulSync] = useState(null);

  const cargarDatos = async () => {
    if (!selectedServer || !selectedSucursal) return;
    setLoading(true);
    setSourceStatus(null);
    setCacheUsed(false);
    try {
      const response = await api.get(`/comercial/ticket-perfecto/${selectedServer}`, {
        params: { sucursal: selectedSucursal }
      });

      // Manejar envelope homologado
      const { source_status, source_message, cache_used, last_successful_sync, data } = response.data;
      setSourceStatus(source_status || 'SUCCESS');
      setSourceMessage(source_message || '');
      setCacheUsed(cache_used || false);
      setLastSuccessfulSync(last_successful_sync || null);

      // Los datos vienen en data o directamente en response.data (backward compatible)
      const ticketResp = data || response.data;
      setTicketData(ticketResp.ticket);
      setRentabilidad(ticketResp.rentabilidad || []);
    } catch (error) {
      logger.error('Error cargando ticket perfecto:', error);
      toast.error('Error al cargar datos de ticket perfecto');
      setSourceStatus('ERROR');
      setTicketData(null);
      setRentabilidad([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (selectedServer && selectedSucursal) cargarDatos();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedServer, selectedSucursal]);

  return (
    <div className="space-y-4">
      {/* Filtros - FASE 3.2: Unidad de Negocio */}
      <Card className="border">
        <CardContent className="py-4">
          <div className="flex items-center gap-4 flex-wrap">
            <div className="flex-1 min-w-[180px] max-w-xs">
              <Label className="text-xs mb-1 block">Unidad de Negocio</Label>
              {unidadesNegocio?.length === 1 ? (
                <div className="flex h-10 w-full items-center rounded-md border border-input bg-zinc-50 px-3 py-2 text-sm">
                  <Building2 className="h-4 w-4 mr-2 text-zinc-500" />{unidadesNegocio[0].nombre}
                </div>
              ) : (
                <Select value={selectedUnidad} onValueChange={setSelectedUnidad} disabled={loadingUnidades}>
                  <SelectTrigger><SelectValue placeholder={loadingUnidades ? "Cargando..." : "Seleccionar unidad"} /></SelectTrigger>
                  <SelectContent>{unidadesNegocio?.map(u => <SelectItem key={u.id} value={u.id}><span className="flex items-center gap-2"><Building2 className="h-3 w-3" />{u.nombre}</span></SelectItem>)}</SelectContent>
                </Select>
              )}
            </div>
            {/* BLINDAJE DEFINITIVO: Selector de Sucursal ELIMINADO - Backend resuelve contexto */}
            <Button onClick={cargarDatos} disabled={loading} className="mt-5">
              {loading ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : <RefreshCw className="h-4 w-4 mr-2" />}
              Actualizar
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* FASE 3A.4: Indicador de estado estructurado - Ticket Perfecto */}
      <ComercialStatusIndicator 
        status={sourceStatus} 
        message={sourceMessage} 
        meta={{ last_successful_sync: lastSuccessfulSync }}
        compact
      />

      {cacheUsed && sourceStatus === 'SUCCESS' && (
        <div className="flex items-center gap-2 text-xs text-amber-600 bg-amber-50 px-3 py-1 rounded-full w-fit">
          <Clock className="h-3 w-3" />
          <span>Datos de cache</span>
        </div>
      )}

      {/* Ticket Perfecto */}
      {ticketData && (
        <Card className="border">
          <CardHeader className="py-3">
            <CardTitle className="text-base flex items-center gap-2">
              <Award className="h-5 w-5 text-yellow-500" />
              Ticket Perfecto (Entrada + Plato Fuerte + Postre + Digestivo)
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
              <div className="text-center p-3 bg-yellow-50 rounded border border-yellow-200">
                <p className="text-xs text-zinc-500">Tickets Completos</p>
                <p className="text-2xl font-bold text-yellow-600">{ticketData.pct_completos}%</p>
                <p className="text-xs text-zinc-500">{ticketData.tickets_completos} de {ticketData.tickets_totales}</p>
              </div>
              <div className="text-center p-3 bg-zinc-50 rounded">
                <Coffee className="h-5 w-5 mx-auto mb-1 text-orange-500" />
                <p className="text-xs text-zinc-500">Con Entrada</p>
                <p className="text-lg font-bold">{ticketData.pct_entrada}%</p>
              </div>
              <div className="text-center p-3 bg-zinc-50 rounded">
                <Utensils className="h-5 w-5 mx-auto mb-1 text-red-500" />
                <p className="text-xs text-zinc-500">Con Plato Fuerte</p>
                <p className="text-lg font-bold">{ticketData.pct_plato_fuerte}%</p>
              </div>
              <div className="text-center p-3 bg-zinc-50 rounded">
                <PieChart className="h-5 w-5 mx-auto mb-1 text-pink-500" />
                <p className="text-xs text-zinc-500">Con Postre</p>
                <p className="text-lg font-bold">{ticketData.pct_postre}%</p>
              </div>
              <div className="text-center p-3 bg-zinc-50 rounded">
                <Wine className="h-5 w-5 mx-auto mb-1 text-purple-500" />
                <p className="text-xs text-zinc-500">Con Digestivo</p>
                <p className="text-lg font-bold">{ticketData.pct_digestivo}%</p>
              </div>
            </div>

            <div className="p-4 bg-red-50 rounded border border-red-200">
              <p className="text-sm text-red-700">
                <AlertTriangle className="h-4 w-4 inline mr-1" />
                <strong>Oportunidad Perdida:</strong> {formatCurrency(ticketData.oportunidad_perdida)} en ventas potenciales por tickets incompletos
              </p>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Rentabilidad por Producto */}
      {rentabilidad.length > 0 && (
        <Card className="border">
          <CardHeader className="py-3">
            <CardTitle className="text-base">Productos por Rentabilidad (Margen de Utilidad)</CardTitle>
          </CardHeader>
          <CardContent className="p-0">
            <div className="max-h-[400px] overflow-auto">
              <table className="w-full text-sm">
                <thead className="sticky top-0 bg-zinc-800 text-white">
                  <tr>
                    <th className="py-2 px-3 text-left">Categoría</th>
                    <th className="py-2 px-3 text-left">Código</th>
                    <th className="py-2 px-3 text-left">Producto</th>
                    <th className="py-2 px-3 text-right">Ventas</th>
                    <th className="py-2 px-3 text-right">Costo</th>
                    <th className="py-2 px-3 text-right">Margen %</th>
                  </tr>
                </thead>
                <tbody>
                  {rentabilidad.map((prod, idx) => (
                    <tr key={prod.producto || `rent-${idx}`} className="border-b hover:bg-zinc-50">
                      <td className="py-2 px-3">
                        <span className={`px-2 py-1 rounded text-xs font-bold ${
                          prod.categoria === 'A' ? 'bg-green-100 text-green-700' :
                          prod.categoria === 'B' ? 'bg-yellow-100 text-yellow-700' :
                          'bg-red-100 text-red-700'
                        }`}>{prod.categoria}</span>
                      </td>
                      <td className="py-2 px-3 font-mono text-xs">{prod.codigo}</td>
                      <td className="py-2 px-3">{prod.producto}</td>
