 * ║ - Mapeo de códigos de sucursal (0023→ORIGEN, 0021→QUERETARO)               ║
 * ║ - Manejo de race conditions al cambiar de unidad                           ║
 * ║                                                                            ║
 * ║ ÚLTIMA VALIDACIÓN: 24-Abril-2026                                           ║
 * ║ FASE 3A.4: Manejo de respuestas estructuradas (Dic-2025)                   ║
 * ║ DEPENDENCIAS: routes.py, adapters.py, service.py, repository.py            ║
 * ╚════════════════════════════════════════════════════════════════════════════╝
 */
import React, { useState, useEffect, useMemo } from 'react';
// AUDITORIA-TABLEROS-KPIS-FILTROS-01: Migrado de axios directo a api centralizado
import api from '../lib/api';
import logger from '../services/logger';
// FASE AUTH-SECURITY-01 / FASE 4.1: getToken eliminado, auth viaja en cookie httpOnly
import { fetchUnidadesNegocio, getServerIdFromUnidad } from '../services/unidadesNegocioService';
import { Card, CardHeader, CardTitle, CardContent } from '../components/ui/card';
import { Button } from '../components/ui/button';
import { Input } from '../components/ui/input';
import { Label } from '../components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../components/ui/select';
import { Checkbox } from '../components/ui/checkbox';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '../components/ui/dialog';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '../components/ui/tabs';
import { Progress } from '../components/ui/progress';
import { toast } from 'sonner';
import { 
  Loader2, TrendingUp, TrendingDown, DollarSign, Users, Clock, Target,
  AlertTriangle, BarChart3, PieChart, ShoppingBag, Utensils, Coffee,
  Wine, Award, RefreshCw, Calendar, ArrowUpRight, ArrowDownRight,
  Receipt, ChevronLeft, ChevronRight, X, Search, ChevronDown, ChevronUp,
  UserCheck, Download, FileSpreadsheet, FileText, Share2, Mail, Scale,
  Building2, Info, AlertCircle, Ban
} from 'lucide-react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, 
  ResponsiveContainer, Cell, ReferenceLine 
} from 'recharts';

// FASE 3A.4: Import de utilidades para respuestas estructuradas
import { 
  getComercialStatusMessage, 
  getStatusStyles, 
  mapHttpErrorToStatus,
  logComercialStatus,
  isErrorStatus,
  canShowData
} from '../utils/comercialStatusUtils';

// P2-13: Helper para resolver server_id desde unidad (evita enviar nombre en vez de UUID)
const resolveServerIdForPrecios = (unidadOrServer) => {
  if (!unidadOrServer) return '';
  if (typeof unidadOrServer === 'string') return unidadOrServer;
  return unidadOrServer.server_id || unidadOrServer.servidor_id || unidadOrServer.id || unidadOrServer.value || '';
};

const API_URL = process.env.REACT_APP_BACKEND_URL;

// ============ FASE 3A.4: COMPONENTE DE ESTADO ESTRUCTURADO ============
/**
 * Componente reutilizable para mostrar estados de respuesta estructurada.
 * Soporta todos los estados de FASE 3A: SUCCESS, NO_DATA, NOT_AVAILABLE_FOR_SYSTEM,
 * UNSUPPORTED_SYSTEM_TYPE, QUERY_ERROR, SOURCE_UNREACHABLE, etc.
 */
const ComercialStatusIndicator = ({ status, message, meta, compact = false }) => {
  if (!status || status === 'SUCCESS') return null;

  const statusInfo = getComercialStatusMessage(status, message, meta);
  const styles = getStatusStyles(status);

  if (!statusInfo.show) return null;

  // Seleccionar ícono según el tipo de estado
  const getIcon = () => {
    switch (status) {
      case 'NO_DATA':
        return <Info className={`h-${compact ? '4' : '6'} w-${compact ? '4' : '6'} ${styles.icon}`} />;
      case 'NOT_AVAILABLE_FOR_SYSTEM':
      case 'UNSUPPORTED_SYSTEM_TYPE':
      case 'INACTIVE_SOURCE':
        return <Ban className={`h-${compact ? '4' : '6'} w-${compact ? '4' : '6'} ${styles.icon}`} />;
      case 'PARTIAL':
      case 'DEGRADED_CACHE':
        return <Clock className={`h-${compact ? '4' : '6'} w-${compact ? '4' : '6'} ${styles.icon}`} />;
      case 'SOURCE_UNREACHABLE':
      case 'QUERY_ERROR':
      case 'FIELD_MAPPING_ERROR':
      case 'CONFIGURATION_MISSING':
      case 'PERMISSION_DENIED':
      case 'ERROR':
      default:
        return <AlertTriangle className={`h-${compact ? '4' : '6'} w-${compact ? '4' : '6'} ${styles.icon}`} />;
    }
  };

  if (compact) {
    return (
      <Card className={`border ${styles.container}`}>
        <CardContent className="py-3">
          <div className="flex items-center gap-2 text-sm">
            {getIcon()}
            <span className={styles.text}>{statusInfo.message}</span>
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className={`border ${styles.container}`} data-testid="comercial-status-indicator">
      <CardContent className="py-4">
        <div className="flex items-center gap-3">
          {getIcon()}
          <div>
            <p className={`font-semibold ${styles.text}`}>{statusInfo.title}</p>
            <p className={`text-sm ${styles.text} opacity-90`}>{statusInfo.message}</p>
            {meta?.last_successful_sync && status === 'DEGRADED_CACHE' && (
              <p className={`text-xs ${styles.text} opacity-70 mt-1`}>
                Última sincronización: {new Date(meta.last_successful_sync).toLocaleString('es-MX')}
              </p>
            )}
          </div>
        </div>
      </CardContent>
    </Card>
  );
};

// ============ UTILIDADES DE FORMATO ============

const formatNumber = (num) => {
  if (num === null || num === undefined) return '-';
  return new Intl.NumberFormat('es-MX', { minimumFractionDigits: 0, maximumFractionDigits: 0 }).format(num);
};

const formatCurrency = (num) => {
  if (num === null || num === undefined) return '-';
  return new Intl.NumberFormat('es-MX', { 
    style: 'currency', 
    currency: 'MXN',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0
  }).format(num);
};

const formatPercent = (num) => {
  if (num === null || num === undefined) return '-';
  return `${num >= 0 ? '+' : ''}${num.toFixed(1)}%`;
};

// ============ MODAL DE DETALLE DE MOVIMIENTOS (Drill-down) ============
function TicketVentaModal({ isOpen, onClose, serverId, sucursal, seleccion }) {
  const [loading, setLoading] = useState(false);
  const [ticket, setTicket] = useState(null);

  useEffect(() => {
    if (!isOpen || !serverId || !seleccion?.folio || !seleccion?.fecha) {
      return;
    }

    const cargarTicket = async () => {
      setLoading(true);
      setTicket(null);
      try {
        const response = await api.get('/comercial/ticket-venta/' + serverId, {
          params: {
            sucursal,
            folio: seleccion.folio,
            fecha: seleccion.fecha
          },
          timeout: 30000
        });
        setTicket(response.data?.ticket || null);
      } catch (error) {
        logger.error('Error cargando ticket de venta:', error);
        toast.error('Error al cargar el ticket de venta');
      } finally {
        setLoading(false);
      }
    };

    cargarTicket();
  }, [isOpen, serverId, sucursal, seleccion]);

  if (!isOpen) return null;

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-lg max-h-[92vh] overflow-auto bg-zinc-100">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Receipt className="h-5 w-5 text-zinc-700" />
            Ticket de Venta
          </DialogTitle>
        </DialogHeader>

        {loading ? (
          <div className="flex justify-center py-14">
            <Loader2 className="h-8 w-8 animate-spin text-zinc-400" />
          </div>
        ) : ticket ? (
          <div className="mx-auto w-full max-w-sm bg-white border border-zinc-300 shadow-sm px-6 py-7 font-mono text-[13px] text-zinc-900">
            <div className="text-center">
              <p className="text-lg font-bold tracking-wide">{ticket.unidad}</p>
              <p className="font-semibold mt-1">TICKET DE SERVICIO</p>
              <p className="text-xs mt-1">{ticket.estado === 'ABIERTA' ? 'VENTA EN CURSO' : 'VENTA CERRADA'}</p>
            </div>

            <div className="border-t border-dashed border-zinc-500 mt-4 pt-3 space-y-1">
              <div className="flex justify-between gap-3">
                <span>FOLIO:</span>
                <span className="font-bold">{ticket.folio}</span>
              </div>
              {ticket.mesa && (
                <div className="flex justify-between gap-3">
                  <span>MESA:</span>
                  <span className="text-right uppercase">{ticket.mesa}</span>
                </div>
              )}
              <div className="flex justify-between gap-3">
                <span>FECHA:</span>
                <span className="text-right">{String(ticket.fecha_hora || '').replace('T', ' ').slice(0, 19)}</span>
              </div>
              {ticket.vendedor && (
                <div className="flex justify-between gap-3">
                  <span>VENDEDOR:</span>
                  <span className="text-right uppercase">{ticket.vendedor}</span>
                </div>
              )}
              {Number(ticket.pax || 0) > 0 && (
                <div className="flex justify-between gap-3">
                  <span>PAX:</span>
                  <span>{ticket.pax}</span>
                </div>
              )}
            </div>

            <div className="border-t border-dashed border-zinc-500 mt-3 pt-3">
              <div className="grid grid-cols-[44px_1fr_88px] gap-2 font-bold pb-2">
                <span>CANT</span>
                <span>DESCRIPCIÓN</span>
                <span className="text-right">IMPORTE</span>
              </div>

              <div className="space-y-2">
                {(ticket.items || []).map((item, idx) => (
                  <div key={idx} className="grid grid-cols-[44px_1fr_88px] gap-2 items-start">
                    <span>{Number(item.cantidad || 0).toLocaleString('es-MX', { maximumFractionDigits: 3 })}</span>
                    <div>
                      <p className="uppercase leading-tight">{item.descripcion}</p>
                      {Number(item.precio_unitario || 0) > 0 && Number(item.cantidad || 0) !== 1 && (
                        <p className="text-[11px] text-zinc-500">
                          @ {formatCurrency(item.precio_unitario)}
                        </p>
                      )}
                    </div>
                    <div className="text-right">
                      <span>{formatCurrency(item.importe_neto ?? item.importe)}</span>
                      {Number(item.descuento_importe || 0) > 0.005 && (
                        <div className="text-[11px] mt-1">
                          <p className="text-zinc-500">
                            BRUTO {formatCurrency(item.importe)}
                          </p>
                          <p className="text-zinc-500">
                            DESC. {Number(item.descuento_pct || 0).toLocaleString('es-MX', { maximumFractionDigits: 2 })}%:
                            {' '}
                            <span className="text-red-600 font-semibold">
                              -{formatCurrency(item.descuento_importe)}
                            </span>
                          </p>
                          <p className="font-semibold">
                            TOTAL PROD. {formatCurrency(item.importe_neto ?? 0)}
                          </p>
                        </div>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            </div>

            <div className="border-t border-dashed border-zinc-500 mt-4 pt-3 space-y-1">
              <div className="flex justify-between">
                <span>SUBTOTAL</span>
                <span>{formatCurrency(ticket.subtotal)}</span>
              </div>
              {Number(ticket.descuento_productos || 0) > 0.005 && (
                <div className="flex justify-between">
                  <span>DESC. PRODUCTOS</span>
                  <span className="text-red-600 font-semibold">-{formatCurrency(ticket.descuento_productos)}</span>
                </div>
              )}
              {Number(ticket.descuento_cuenta || 0) > 0.005 && (
                <div className="flex justify-between">
                  <span>DESC. CUENTA</span>
                  <span className="text-red-600 font-semibold">-{formatCurrency(ticket.descuento_cuenta)}</span>
                </div>
              )}
              {Number(ticket.descuento || 0) > 0.005 &&
               Number(ticket.descuento_productos || 0) <= 0.005 &&
               Number(ticket.descuento_cuenta || 0) <= 0.005 && (
                <div className="flex justify-between">
                  <span>DESCUENTO</span>
                  <span className="text-red-600 font-semibold">-{formatCurrency(ticket.descuento)}</span>
                </div>
              )}
              {ticket.impuesto != null && (
                <div className="flex justify-between">
                  <span>IMPUESTO</span>
                  <span>{formatCurrency(ticket.impuesto)}</span>
                </div>
              )}
              <div className="flex justify-between text-base font-bold border-t border-zinc-900 mt-2 pt-2">
                <span>TOTAL VENTA</span>
                <span>{formatCurrency(ticket.total)}</span>
              </div>
              {Number(ticket.propina || 0) > 0.005 && (
                <div className="flex justify-between">
                  <span>PROPINA</span>
                  <span>{formatCurrency(ticket.propina)}</span>
                </div>
              )}
            </div>

            <div className="border-t border-dashed border-zinc-500 mt-5 pt-4 text-center text-[11px] text-zinc-500">
              <p>EDARSA HUB · CONSULTA DE VENTA</p>
            </div>
          </div>
        ) : (
          <div className="text-center py-12 text-zinc-500">
            <Receipt className="h-10 w-10 mx-auto mb-3 opacity-30" />
            <p>No se encontró información para este folio.</p>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}


// ============ MODAL DE DETALLE DE MOVIMIENTOS (Drill-down) ============
function DetalleMovimientosModal({ isOpen, onClose, serverId, sucursal, periodo, tipoKpi, selectedMeses, selectedAnios }) {
  const [loading, setLoading] = useState(false);
  const [data, setData] = useState(null);
  const [page, setPage] = useState(1);
  const [ventasTree, setVentasTree] = useState({});
  const [ticketSeleccionado, setTicketSeleccionado] = useState(null);

  const titulos = {
    ventas: { titulo: 'Detalle de Ventas', icono: DollarSign, color: 'text-green-600' },
    ticket: { titulo: 'Detalle de Cheques', icono: Receipt, color: 'text-blue-600' },
    pax: { titulo: 'Detalle PAX Total', icono: Users, color: 'text-purple-600' },
    pax_promedio: { titulo: 'Detalle PAX Promedio por Cuenta', icono: Users, color: 'text-purple-600' },
    rotacion: { titulo: 'Rotación de Mesas por Mes', icono: Utensils, color: 'text-orange-600' }
  };

  const config = titulos[tipoKpi] || titulos.ventas;
  const IconComponent = config.icono;
  const esRotacion = tipoKpi === 'rotacion';
  const esPaxPromedio = tipoKpi === 'pax_promedio';
  const esVentas = tipoKpi === 'ventas';

  useEffect(() => {
    setPage(1);
    setVentasTree({});
    setTicketSeleccionado(null);
  }, [tipoKpi, selectedMeses, selectedAnios, periodo]);

  useEffect(() => {
    if (isOpen && serverId && sucursal) {
      cargarDetalle();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isOpen, serverId, sucursal, page, periodo, tipoKpi, selectedMeses, selectedAnios]);

  const baseParams = () => ({
    sucursal,
    periodo,
    meses: selectedMeses?.join(',') || '',
    anios: selectedAnios?.join(',') || ''
  });

  const cargarDetalle = async () => {
    setLoading(true);
    try {
      const endpoint = esVentas
        ? '/comercial/detalle-ventas-agrupado/' + serverId
        : '/comercial/detalle-movimientos/' + serverId;

      const params = esVentas
        ? { ...baseParams(), nivel: 'auto', page: 1, limit: 5000 }
        : { ...baseParams(), tipo: tipoKpi, page, limit: 50 };

      const response = await api.get(endpoint, { params, timeout: 30000 });
      const payload = response.data || {};
      if (payload.source_status === 'ERROR') {
        throw new Error(payload.source_message || 'Error al consultar detalle');
      }
      setData(payload);
      if (esVentas) setVentasTree({});
    } catch (error) {
      logger.error('Error cargando detalle:', error);
      toast.error('Error al cargar detalle de movimientos');
    } finally {
      setLoading(false);
    }
  };

  const toggleGrupoVentas = async (grupo) => {
    if (!grupo?.expandible || !grupo?.clave) return;

    const actual = ventasTree[grupo.clave];
    if (actual?.open) {
      setVentasTree(prev => ({
        ...prev,
        [grupo.clave]: { ...prev[grupo.clave], open: false }
      }));
      return;
    }

    if (actual?.children) {
      setVentasTree(prev => ({
        ...prev,
        [grupo.clave]: { ...prev[grupo.clave], open: true }
      }));
      return;
    }

    setVentasTree(prev => ({
      ...prev,
      [grupo.clave]: { open: true, loading: true, children: null }
    }));

    try {
      const params = { ...baseParams(), nivel: grupo.siguiente_nivel, page: 1, limit: 5000 };
      if (grupo.anio) params.anio_filtro = grupo.anio;
      if (grupo.mes) params.mes_filtro = grupo.mes;
      if (grupo.fecha) params.fecha_filtro = grupo.fecha;

      const response = await api.get(
        '/comercial/detalle-ventas-agrupado/' + serverId,
        { params, timeout: 30000 }
      );
      const payload = response.data || {};
      if (payload.source_status === 'ERROR') {
        throw new Error(payload.source_message || 'Error al consultar el grupo');
      }

      setVentasTree(prev => ({
        ...prev,
        [grupo.clave]: {
          open: true,
          loading: false,
          children: payload.items || payload.movimientos || []
        }
      }));
    } catch (error) {
      logger.error('Error cargando grupo de ventas:', error);
      setVentasTree(prev => ({
        ...prev,
        [grupo.clave]: { open: false, loading: false, children: null }
      }));
      toast.error('Error al abrir el detalle del período');
    }
  };

  const abrirTicket = (item) => {
    const fecha = String(item?.fecha || '').slice(0, 10);
    if (!item?.folio || !fecha) return;
    setTicketSeleccionado({ folio: item.folio, fecha });
  };

  const renderVentasRows = (items, depth = 0) => (items || []).map((item, idx) => {
    const esDetalle = item.nivel === 'detalle';
    const state = item.clave ? ventasTree[item.clave] : null;
    const rowKey = item.clave || ((item.folio || 'venta') + '-' + (item.fecha || idx) + '-' + depth);

    return (
      <React.Fragment key={rowKey}>
        <tr
          className={
            'border-b transition-colors ' +
            ((item.expandible || esDetalle) ? 'hover:bg-zinc-50 cursor-pointer' : 'hover:bg-zinc-50')
          }
          onClick={() => {
            if (esDetalle) {
              abrirTicket(item);
            } else if (item.expandible) {
              toggleGrupoVentas(item);
            }
          }}
          title={esDetalle ? 'Abrir ticket de venta' : undefined}
        >
          <td className="py-2 px-3">
            <div className="flex items-center gap-1" style={{ paddingLeft: (depth * 18) + 'px' }}>
              {item.expandible ? (
                state?.loading ? (
                  <Loader2 className="h-4 w-4 animate-spin text-zinc-400 flex-shrink-0" />
                ) : state?.open ? (
                  <ChevronDown className="h-4 w-4 text-zinc-500 flex-shrink-0" />
                ) : (
                  <ChevronRight className="h-4 w-4 text-zinc-500 flex-shrink-0" />
                )
              ) : esDetalle ? (
                <Receipt className="h-4 w-4 text-zinc-400 flex-shrink-0" />
              ) : (
                <span className="w-4" />
              )}
              <span className={esDetalle ? 'font-mono text-xs font-medium underline decoration-dotted underline-offset-2' : 'font-semibold'}>
                {esDetalle ? item.folio : item.label}
              </span>
              {esDetalle && item.total_cero_por_descuento && (
                <span className="inline-flex items-center rounded border border-amber-300 bg-amber-50 px-1.5 py-0.5 text-[10px] font-semibold text-amber-700">
                  TOTAL $0 · DESCUENTO
                </span>
              )}
            </div>
          </td>
          <td className="py-2 px-3 text-zinc-600">
            {esDetalle ? item.fecha : (item.nivel === 'dia' ? item.fecha : '-')}
          </td>
          <td className="py-2 px-3 text-right">
            {esDetalle ? '-' : formatNumber(item.folios)}
          </td>
          <td className="py-2 px-3 text-center">
            {Number(item.pax || 0) > 0 ? (
              <span className="inline-flex items-center gap-1">
                <Users className="h-3 w-3 text-purple-500" />
                {formatNumber(item.pax)}
              </span>
            ) : '-'}
          </td>
          <td className="py-2 px-3 text-right font-semibold text-green-600">
            {formatCurrency(item.total_venta ?? item.importe)}
          </td>
        </tr>
        {state?.open && state?.children && renderVentasRows(state.children, depth + 1)}
      </React.Fragment>
    );
  });

  if (!isOpen) return null;

  const ventasItems = data?.items || data?.movimientos || [];
  const hayDatos = esVentas ? ventasItems.length > 0 : data?.movimientos?.length > 0;

  return (
    <>
      <Dialog open={isOpen} onOpenChange={onClose}>
        <DialogContent className="max-w-5xl max-h-[88vh] overflow-hidden flex flex-col">
          <DialogHeader className="flex-shrink-0">
            <DialogTitle className="flex items-center gap-2">
              <IconComponent className={'h-5 w-5 ' + config.color} />
              {config.titulo}
              {data?.servidor && <span className="text-sm font-normal text-zinc-500">• {data.servidor}</span>}
            </DialogTitle>
          </DialogHeader>

          {loading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="h-8 w-8 animate-spin text-zinc-400" />
            </div>
          ) : hayDatos ? (
            <div className="flex-1 overflow-hidden flex flex-col">
              <div className="flex items-center justify-between mb-3 px-1">
                <span className="text-sm text-zinc-500">
                  Período: {data.periodo?.inicio} a {data.periodo?.fin}
                </span>
                <span className="text-sm font-medium">
                  {esVentas
                    ? (formatNumber(data.resumen_periodo?.folios || 0) + ' folio(s)')
                    : (data.total + ' ' + (esRotacion ? 'mes(es)' : 'folio(s)'))}
                </span>
              </div>

              {esVentas && (
                <p className="text-xs text-zinc-500 mb-2 px-1">
                  Selecciona un folio para abrir el ticket de venta.
                </p>
              )}

              <div className="flex-1 overflow-auto border rounded-lg">
                <table className="w-full text-sm">
                  <thead className="sticky top-0 bg-zinc-800 text-white z-10">
                    {esVentas ? (
                      <tr>
                        <th className="py-2 px-3 text-left">Período / Folio</th>
                        <th className="py-2 px-3 text-left">Fecha</th>
                        <th className="py-2 px-3 text-right">Folios</th>
                        <th className="py-2 px-3 text-center">PAX</th>
                        <th className="py-2 px-3 text-right">Total Venta</th>
                      </tr>
                    ) : esRotacion ? (
                      <tr>
                        <th className="py-2 px-3 text-left">Mes</th>
                        <th className="py-2 px-3 text-right">Rotación</th>
                        <th className="py-2 px-3 text-right">Cheques</th>
                        <th className="py-2 px-3 text-right">PAX</th>
                      </tr>
                    ) : (
                      <tr>
                        <th className="py-2 px-3 text-left">Folio</th>
                        <th className="py-2 px-3 text-left">Fecha</th>
                        <th className="py-2 px-3 text-center">PAX</th>
                        <th className="py-2 px-3 text-right">Total Venta</th>
                        {esPaxPromedio && <th className="py-2 px-3 text-right">PAX Promedio</th>}
                      </tr>
                    )}
                  </thead>
                  <tbody>
                    {esVentas ? renderVentasRows(ventasItems) : data.movimientos.map((mov, idx) => (
                      esRotacion ? (
                        <tr key={mov.folio || ('rot-' + idx)} className="border-b hover:bg-zinc-50 transition-colors">
                          <td className="py-2 px-3 font-medium">{mov.mes_label || mov.fecha}</td>
                          <td className="py-2 px-3 text-right font-semibold">{Number(mov.rotacion || 0).toFixed(2)}x</td>
                          <td className="py-2 px-3 text-right">{formatNumber(mov.cheques)}</td>
                          <td className="py-2 px-3 text-right">{formatNumber(mov.pax)}</td>
                        </tr>
                      ) : (
                        <tr key={(mov.folio || 'mov') + '-' + idx} className="border-b hover:bg-zinc-50 transition-colors">
                          <td className="py-2 px-3 font-mono text-xs font-medium">{mov.folio}</td>
                          <td className="py-2 px-3 text-zinc-600">{mov.fecha}</td>
                          <td className="py-2 px-3 text-center">
                            {mov.pax > 0 ? (
                              <span className="inline-flex items-center gap-1">
                                <Users className="h-3 w-3 text-purple-500" />
                                {mov.pax}
                              </span>
                            ) : '-'}
                          </td>
                          <td className="py-2 px-3 text-right font-semibold text-green-600">
                            {formatCurrency(mov.importe)}
                          </td>
                          {esPaxPromedio && (
                            <td className="py-2 px-3 text-right font-semibold text-purple-600">
                              {mov.pax_promedio == null ? '-' : formatCurrency(mov.pax_promedio)}
                            </td>
                          )}
                        </tr>
                      )
                    ))}
                  </tbody>
                </table>
              </div>

              {esVentas && (
                <div className="mt-3 rounded-lg border bg-zinc-50 px-4 py-3 flex items-center justify-between gap-4">
                  <div>
                    <p className="text-xs uppercase tracking-wide text-zinc-500">Total del período seleccionado</p>
                    <p className="text-xs text-zinc-500">
                      {formatNumber(data.resumen_periodo?.folios || 0)} folio(s) • {formatNumber(data.resumen_periodo?.pax || 0)} PAX
                    </p>
                  </div>
                  <p className="text-xl font-bold text-green-600">
                    {formatCurrency(data.resumen_periodo?.total_venta || 0)}
                  </p>
                </div>
              )}

              {!esVentas && !esRotacion && data.pages > 1 && (
                <div className="flex items-center justify-between pt-3 border-t mt-3">
                  <Button variant="outline" size="sm" onClick={() => setPage(p => Math.max(1, p - 1))} disabled={page <= 1}>
                    <ChevronLeft className="h-4 w-4 mr-1" /> Anterior
                  </Button>
                  <span className="text-sm text-zinc-500">Página {page} de {data.pages}</span>
                  <Button variant="outline" size="sm" onClick={() => setPage(p => Math.min(data.pages, p + 1))} disabled={page >= data.pages}>
                    Siguiente <ChevronRight className="h-4 w-4 ml-1" />
                  </Button>
                </div>
              )}
            </div>
          ) : (
            <div className="text-center py-12 text-zinc-500">
              <Receipt className="h-12 w-12 mx-auto mb-3 opacity-30" />
              <p>No hay movimientos en este período</p>
            </div>
          )}
        </DialogContent>
      </Dialog>

      <TicketVentaModal
        isOpen={Boolean(ticketSeleccionado)}
        onClose={() => setTicketSeleccionado(null)}
        serverId={serverId}
        sucursal={sucursal}
        seleccion={ticketSeleccionado}
      />
    </>
  );
}

// ============ TAB 1: DASHBOARD DE VENTAS ============
// Constantes para meses y años
const MESES = [
  { value: '01', label: 'Enero' },
  { value: '02', label: 'Febrero' },
  { value: '03', label: 'Marzo' },
  { value: '04', label: 'Abril' },
  { value: '05', label: 'Mayo' },
  { value: '06', label: 'Junio' },
  { value: '07', label: 'Julio' },
  { value: '08', label: 'Agosto' },
  { value: '09', label: 'Septiembre' },
  { value: '10', label: 'Octubre' },
  { value: '11', label: 'Noviembre' },
  { value: '12', label: 'Diciembre' }
];

const getAniosDisponibles = () => {
  const currentYear = new Date().getFullYear();
  const years = [];
  for (let y = currentYear; y >= currentYear - 5; y--) {
    years.push({ value: y.toString(), label: y.toString() });
  }
  return years;
};

function DashboardVentas({ servers, unidadesNegocio, selectedUnidad, setSelectedUnidad, selectedServer, setSelectedServer, selectedSucursal, setSelectedSucursal, sucursales, showSucursalSelector, loadingUnidades }) {
  const [loading, setLoading] = useState(false);
  const [kpis, setKpis] = useState(null);
  const [comparativo, setComparativo] = useState(null);
  const [alertas, setAlertas] = useState([]);
  const [periodo, setPeriodo] = useState('mes'); // mes, semana, dia
  const [selectedMeses, setSelectedMeses] = useState([String(new Date().getMonth() + 1).padStart(2, '0')]);
  const [selectedAnios, setSelectedAnios] = useState([new Date().getFullYear().toString()]);
  const [showMesesDropdown, setShowMesesDropdown] = useState(false);
  const [showAniosDropdown, setShowAniosDropdown] = useState(false);
  const [detalleModal, setDetalleModal] = useState({ open: false, tipo: null });
  const [tipoComparacion, setTipoComparacion] = useState('dias_equiv'); // dias_equiv o mes_completo

  // Estado de fuente de datos (SourceQueryResult pattern)
  const [sourceStatus, setSourceStatus] = useState(null); // SUCCESS, NO_DATA, SOURCE_UNREACHABLE, DEGRADED_CACHE, ERROR
  const [sourceMessage, setSourceMessage] = useState('');
  const [cacheUsed, setCacheUsed] = useState(false); // Indica si los datos vienen de cache
  const [lastSuccessfulSync, setLastSuccessfulSync] = useState(null); // Timestamp de última sincronización exitosa

  const ANIOS = getAniosDisponibles();

  // Detectar si hay multiselección de meses (para deshabilitar "vs mes")
  const esMultiMes = selectedMeses.length > 1;

  const cargarDashboard = async () => {
    if (!selectedServer || !selectedSucursal) {
      toast.error('Selecciona unidad de negocio');
      return;
    }

    // ========== VALIDACIÓN: Verificar que la sucursal pertenece a la unidad actual ==========
    // Esto evita race conditions cuando se cambia de unidad de negocio
    const unidadActual = unidadesNegocio.find(u => u.id === selectedUnidad);
    if (unidadActual) {
      const sucursalesValidas = unidadActual.sucursales || [];
      const esValida = sucursalesValidas.some(s => 
        (s.id || s.codigo || s.nombre) === selectedSucursal
      ) || selectedSucursal === unidadActual.sucursal_origen_id || selectedSucursal === 'default';

      if (!esValida && sucursalesValidas.length > 0) {
        logger.warn(`[Dashboard] Sucursal '${selectedSucursal}' no pertenece a unidad '${unidadActual.nombre}'. Esperando actualización...`);
        return; // No cargar, esperar a que se actualice la sucursal
      }
    }

    setLoading(true);
    setSourceStatus(null);
    setSourceMessage('');
    setCacheUsed(false);
    setLastSuccessfulSync(null);
    try {
      const response = await api.get(`/comercial/dashboard/${selectedServer}`, {
        params: { 
          sucursal: selectedSucursal, 
          periodo,
          meses: selectedMeses.join(','),
          anios: selectedAnios.join(','),
          tipo_comparacion: tipoComparacion
        }
      });

      // Manejar source_status del backend
      const { source_status, source_message, cache_used, last_successful_sync, kpis: kpisData, comparativo: compData, alertas: alertasData } = response.data;

      setSourceStatus(source_status || 'SUCCESS');
      setSourceMessage(source_message || '');
      setCacheUsed(cache_used || false);
      setLastSuccessfulSync(last_successful_sync || null);

      if (source_status === 'SUCCESS' || source_status === 'NO_DATA' || source_status === 'DEGRADED_CACHE') {
        setKpis(kpisData);
        setComparativo(compData);
        setAlertas(alertasData || []);
      } else if (source_status === 'SOURCE_UNREACHABLE') {
        setKpis(null);
        setComparativo(null);
        setAlertas([{ tipo: 'error', mensaje: source_message }]);
        toast.error(`Servidor inalcanzable: ${response.data.server_name || 'desconocido'}`);
      } else {
        setKpis(kpisData);
        setComparativo(compData);
        setAlertas(alertasData || []);
      }
    } catch (error) {
      logger.error('Error cargando dashboard:', error);
      setSourceStatus('ERROR');
      setSourceMessage(error.message || 'Error de conexión');
      toast.error('Error al cargar datos de ventas');
      setKpis(null);
      setComparativo(null);
      setAlertas([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (selectedServer && selectedSucursal) {
      cargarDashboard();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedServer, selectedSucursal, periodo, selectedMeses, selectedAnios, tipoComparacion]);

  const toggleMes = (mes) => {
    setSelectedMeses(prev => {
      if (prev.includes(mes)) {
        if (prev.length === 1) return prev; // Al menos un mes debe estar seleccionado
        return prev.filter(m => m !== mes);
      }
      return [...prev, mes].sort();
    });
  };

  const toggleAnio = (anio) => {
    setSelectedAnios(prev => {
      if (prev.includes(anio)) {
        if (prev.length === 1) return prev; // Al menos un año debe estar seleccionado
        return prev.filter(a => a !== anio);
      }
      return [...prev, anio].sort().reverse(); // Ordenar descendente
    });
  };

  const getMesesLabel = () => {
    if (selectedMeses.length === 0) return 'Seleccionar';
    if (selectedMeses.length === 1) {
      return MESES.find(m => m.value === selectedMeses[0])?.label || 'Mes';
    }
    if (selectedMeses.length === 12) return 'Todo el año';
    return `${selectedMeses.length} meses`;
  };

  const getAniosLabel = () => {
    if (selectedAnios.length === 0) return 'Seleccionar';
    if (selectedAnios.length === 1) {
      return selectedAnios[0];
    }
    return `${selectedAnios.length} años`;
  };

  const handleDoubleClick = (tipoKpi) => {
    if (!selectedServer || !selectedSucursal) {
      toast.error('Selecciona unidad de negocio y sucursal primero');
      return;
    }
    setDetalleModal({ open: true, tipo: tipoKpi });
  };

  return (
    <div className="space-y-4">
      {/* Filtros - FASE 3.2: Unidad de Negocio */}
      <Card className="border">
        <CardContent className="py-4">
          <div className="flex items-center gap-4 flex-wrap">
            <div className="flex-1 min-w-[180px] max-w-xs">
              <Label className="text-xs mb-1 block">Unidad de Negocio</Label>
              {unidadesNegocio?.length === 1 ? (
                <div className="flex h-10 w-full items-center rounded-md border border-input bg-zinc-50 px-3 py-2 text-sm">
                  <Building2 className="h-4 w-4 mr-2 text-zinc-500" />
                  {unidadesNegocio[0].nombre}
                </div>
              ) : (
                <Select value={selectedUnidad} onValueChange={setSelectedUnidad} disabled={loadingUnidades}>
                  <SelectTrigger data-testid="comercial-unidad-selector">
                    <SelectValue placeholder={loadingUnidades ? "Cargando..." : "Seleccionar unidad"} />
                  </SelectTrigger>
                  <SelectContent>
                    {unidadesNegocio?.map(u => (
                      <SelectItem key={u.id} value={u.id}>
                        <span className="flex items-center gap-2">
                          <Building2 className="h-3 w-3" />
                          {u.nombre}
                        </span>
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              )}
            </div>
            {/* BLINDAJE DEFINITIVO: Selector de Sucursal ELIMINADO - Backend resuelve contexto */}
            <div className="flex-1 min-w-[120px] max-w-[150px]">
              <Label className="text-xs mb-1 block">Período</Label>
              <Select value={periodo} onValueChange={setPeriodo}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="dia">Hoy</SelectItem>
                  <SelectItem value="semana">Semana</SelectItem>
