// ============ TAB 2: TICKET PERFECTO Y RENTABILIDAD ============
function TicketPerfecto({ servers, unidadesNegocio, selectedUnidad, setSelectedUnidad, selectedServer, setSelectedServer, selectedSucursal, setSelectedSucursal, sucursales, showSucursalSelector, loadingUnidades }) {
  const [loading, setLoading] = useState(false);
  const [ticketData, setTicketData] = useState(null);
  const [rentabilidad, setRentabilidad] = useState([]);
  const [sourceStatus, setSourceStatus] = useState(null);
  const [sourceMessage, setSourceMessage] = useState('');
  const [cacheUsed, setCacheUsed] = useState(false);
  const [lastSuccessfulSync, setLastSuccessfulSync] = useState(null);

  const cargarDatos = async () => {
    if (!selectedServer || !selectedSucursal) return;
    setLoading(true);
    setSourceStatus(null);
    setCacheUsed(false);
    try {
      const response = await api.get(`/comercial/ticket-perfecto/${selectedServer}`, {
        params: { sucursal: selectedSucursal }
      });

      // Manejar envelope homologado
      const { source_status, source_message, cache_used, last_successful_sync, data } = response.data;
      setSourceStatus(source_status || 'SUCCESS');
      setSourceMessage(source_message || '');
      setCacheUsed(cache_used || false);
      setLastSuccessfulSync(last_successful_sync || null);

      // Los datos vienen en data o directamente en response.data (backward compatible)
      const ticketResp = data || response.data;
      setTicketData(ticketResp.ticket);
      setRentabilidad(ticketResp.rentabilidad || []);
    } catch (error) {
      logger.error('Error cargando ticket perfecto:', error);
      toast.error('Error al cargar datos de ticket perfecto');
      setSourceStatus('ERROR');
      setTicketData(null);
      setRentabilidad([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (selectedServer && selectedSucursal) cargarDatos();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedServer, selectedSucursal]);

  return (
    <div className="space-y-4">
      {/* Filtros - FASE 3.2: Unidad de Negocio */}
      <Card className="border">
        <CardContent className="py-4">
          <div className="flex items-center gap-4 flex-wrap">
            <div className="flex-1 min-w-[180px] max-w-xs">
              <Label className="text-xs mb-1 block">Unidad de Negocio</Label>
              {unidadesNegocio?.length === 1 ? (
                <div className="flex h-10 w-full items-center rounded-md border border-input bg-zinc-50 px-3 py-2 text-sm">
                  <Building2 className="h-4 w-4 mr-2 text-zinc-500" />{unidadesNegocio[0].nombre}
                </div>
              ) : (
                <Select value={selectedUnidad} onValueChange={setSelectedUnidad} disabled={loadingUnidades}>
                  <SelectTrigger><SelectValue placeholder={loadingUnidades ? "Cargando..." : "Seleccionar unidad"} /></SelectTrigger>
                  <SelectContent>{unidadesNegocio?.map(u => <SelectItem key={u.id} value={u.id}><span className="flex items-center gap-2"><Building2 className="h-3 w-3" />{u.nombre}</span></SelectItem>)}</SelectContent>
                </Select>
              )}
            </div>
            {/* BLINDAJE DEFINITIVO: Selector de Sucursal ELIMINADO - Backend resuelve contexto */}
            <Button onClick={cargarDatos} disabled={loading} className="mt-5">
              {loading ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : <RefreshCw className="h-4 w-4 mr-2" />}
              Actualizar
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* FASE 3A.4: Indicador de estado estructurado - Ticket Perfecto */}
      <ComercialStatusIndicator 
        status={sourceStatus} 
        message={sourceMessage} 
        meta={{ last_successful_sync: lastSuccessfulSync }}
        compact
      />

      {cacheUsed && sourceStatus === 'SUCCESS' && (
        <div className="flex items-center gap-2 text-xs text-amber-600 bg-amber-50 px-3 py-1 rounded-full w-fit">
          <Clock className="h-3 w-3" />
          <span>Datos de cache</span>
        </div>
      )}

