// ============ TAB 3: METAS DE VENTAS ============
function MetasVentas({ servers, unidadesNegocio, selectedUnidad, setSelectedUnidad, selectedServer, setSelectedServer, selectedSucursal, setSelectedSucursal, sucursales, showSucursalSelector, loadingUnidades }) {
  const [loading, setLoading] = useState(false);
  const [metasProducto, setMetasProducto] = useState([]);
  const [metasVendedor, setMetasVendedor] = useState([]);
  const [sourceStatus, setSourceStatus] = useState(null);
  const [sourceMessage, setSourceMessage] = useState('');
  const [cacheUsed, setCacheUsed] = useState(false);
  const [lastSuccessfulSync, setLastSuccessfulSync] = useState(null);

  const cargarMetas = async () => {
    if (!selectedServer || !selectedSucursal) return;
    setLoading(true);
    setSourceStatus(null);
    setCacheUsed(false);
    try {
      const response = await api.get(`/comercial/metas/${selectedServer}`, {
        params: { sucursal: selectedSucursal }
      });

      // Manejar envelope homologado
      const { source_status, source_message, cache_used, last_successful_sync, data } = response.data;
      setSourceStatus(source_status || 'SUCCESS');
      setSourceMessage(source_message || '');
      setCacheUsed(cache_used || false);
      setLastSuccessfulSync(last_successful_sync || null);

      // Los datos vienen en data o directamente en response.data (backward compatible)
      const metasData = data || response.data;
      setMetasProducto(metasData.por_producto || []);
      setMetasVendedor(metasData.por_vendedor || []);
    } catch (error) {
      logger.error('Error cargando metas:', error);
      toast.error('Error al cargar metas');
      setSourceStatus('ERROR');
      setMetasProducto([]);
      setMetasVendedor([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (selectedServer && selectedSucursal) cargarMetas();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedServer, selectedSucursal]);

  return (
    <div className="space-y-4">
      {/* Filtros */}
      <Card className="border">
        <CardContent className="py-4">
          <div className="flex items-center gap-4 flex-wrap">
            <div className="flex-1 min-w-[180px] max-w-xs">
              <Label className="text-xs mb-1 block">Unidad de Negocio</Label>
              {unidadesNegocio?.length === 1 ? (
                <div className="flex h-10 w-full items-center rounded-md border border-input bg-zinc-50 px-3 py-2 text-sm">
                  <Building2 className="h-4 w-4 mr-2 text-zinc-500" />{unidadesNegocio[0].nombre}
                </div>
              ) : (
                <Select value={selectedUnidad} onValueChange={setSelectedUnidad} disabled={loadingUnidades}>
                  <SelectTrigger><SelectValue placeholder={loadingUnidades ? "Cargando..." : "Seleccionar unidad"} /></SelectTrigger>
                  <SelectContent>{unidadesNegocio?.map(u => <SelectItem key={u.id} value={u.id}><span className="flex items-center gap-2"><Building2 className="h-3 w-3" />{u.nombre}</span></SelectItem>)}</SelectContent>
                </Select>
              )}
            </div>
            {/* BLINDAJE DEFINITIVO: Selector de Sucursal ELIMINADO - Backend resuelve contexto */}
            <Button onClick={cargarMetas} disabled={loading} className="mt-5">
              {loading ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : <Target className="h-4 w-4 mr-2" />}
              Cargar Metas
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* FASE 3A.4: Indicador de estado estructurado - Metas */}
      <ComercialStatusIndicator 
        status={sourceStatus} 
        message={sourceMessage} 
        meta={{ last_successful_sync: lastSuccessfulSync }}
        compact
      />

      {cacheUsed && sourceStatus === 'SUCCESS' && (
        <div className="flex items-center gap-2 text-xs text-amber-600 bg-amber-50 px-3 py-1 rounded-full w-fit">
          <Clock className="h-3 w-3" />
          <span>Datos de cache</span>
        </div>
      )}

      <div className="grid md:grid-cols-2 gap-4">
        {/* Metas por Producto */}
        <Card className="border">
          <CardHeader className="py-3">
            <CardTitle className="text-base">Metas por Producto</CardTitle>
          </CardHeader>
          <CardContent className="space-y-3">
            {metasProducto.map((m, idx) => (
              <div key={m.producto || `meta-prod-${idx}`} className="p-3 bg-zinc-50 rounded">
                <div className="flex justify-between items-center mb-2">
                  <span className="font-medium">{m.producto}</span>
                  <span className={`font-bold ${m.cumplimiento >= 100 ? 'text-green-600' : m.cumplimiento >= 80 ? 'text-yellow-600' : 'text-red-600'}`}>
                    {m.cumplimiento}%
                  </span>
                </div>
                <Progress value={Math.min(m.cumplimiento, 100)} className="h-2 mb-1" />
                <div className="flex justify-between text-xs text-zinc-500">
                  <span>Real: {formatCurrency(m.real)}</span>
                  <span>Meta: {formatCurrency(m.meta)}</span>
                </div>
              </div>
            ))}
          </CardContent>
        </Card>

        {/* Metas por Vendedor */}
        <Card className="border">
          <CardHeader className="py-3">
            <CardTitle className="text-base">Metas por Vendedor</CardTitle>
          </CardHeader>
          <CardContent className="space-y-3">
            {metasVendedor.map((m, idx) => (
              <div key={m.vendedor || `meta-vend-${idx}`} className="p-3 bg-zinc-50 rounded">
                <div className="flex justify-between items-center mb-2">
                  <span className="font-medium">{m.vendedor}</span>
                  <span className={`font-bold ${m.cumplimiento >= 100 ? 'text-green-600' : m.cumplimiento >= 80 ? 'text-yellow-600' : 'text-red-600'}`}>
                    {m.cumplimiento}%
                  </span>
                </div>
                <Progress value={Math.min(m.cumplimiento, 100)} className="h-2 mb-1" />
                <div className="flex justify-between text-xs text-zinc-500">
                  <span>Real: {formatCurrency(m.real)}</span>
                  <span>Meta: {formatCurrency(m.meta)}</span>
                </div>
              </div>
            ))}
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

// ============ TAB 4: VENTAS POR HORA/DÍA ============
function VentasPorTiempo({ servers, unidadesNegocio, selectedUnidad, setSelectedUnidad, selectedServer, setSelectedServer, selectedSucursal, setSelectedSucursal, sucursales, showSucursalSelector, loadingUnidades }) {
  const [loading, setLoading] = useState(false);
  const [ventasPorHora, setVentasPorHora] = useState([]);
  const [ventasPorDia, setVentasPorDia] = useState([]);
  const [paxHoy, setPaxHoy] = useState(0);
  const [ventasHoy, setVentasHoy] = useState(0);
  const [chequesHoy, setChequesHoy] = useState(0);
  const [fuentePaxHoy, setFuentePaxHoy] = useState('');

  const cargarDatos = async () => {
    if (!selectedServer || !selectedSucursal) return;
    setLoading(true);
    try {
      const response = await api.get(`/comercial/ventas-tiempo/${selectedServer}`, {
        params: { sucursal: selectedSucursal }
      });
      setVentasPorHora(response.data.por_hora || []);
      setVentasPorDia(response.data.por_dia || []);
      setPaxHoy(response.data.pax_hoy || 0);
      setVentasHoy(response.data.ventas_hoy || 0);
      setChequesHoy(response.data.cheques_hoy || 0);
      setFuentePaxHoy(response.data.fuente_pax_hoy || '');
    } catch (error) {
      logger.error('Error cargando ventas por tiempo:', error);
      toast.error('Error al cargar datos por hora/día');
      setVentasPorHora([]);
      setVentasPorDia([]);
      setPaxHoy(0);
      setVentasHoy(0);
      setChequesHoy(0);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (selectedServer && selectedSucursal) cargarDatos();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedServer, selectedSucursal]);

  const maxVentaHora = Math.max(...ventasPorHora.map(v => v.ventas), 1);
  const maxVentaDia = Math.max(...ventasPorDia.map(v => v.ventas), 1);

  return (
    <div className="space-y-4">
      {/* Filtros - FASE 3.2: Unidad de Negocio */}
      <Card className="border">
        <CardContent className="py-4">
          <div className="flex items-center gap-4 flex-wrap">
            <div className="flex-1 min-w-[180px] max-w-xs">
              <Label className="text-xs mb-1 block">Unidad de Negocio</Label>
              {unidadesNegocio?.length === 1 ? (
                <div className="flex h-10 w-full items-center rounded-md border border-input bg-zinc-50 px-3 py-2 text-sm">
                  <Building2 className="h-4 w-4 mr-2 text-zinc-500" />{unidadesNegocio[0].nombre}
                </div>
              ) : (
                <Select value={selectedUnidad} onValueChange={setSelectedUnidad} disabled={loadingUnidades}>
                  <SelectTrigger><SelectValue placeholder={loadingUnidades ? "Cargando..." : "Seleccionar unidad"} /></SelectTrigger>
                  <SelectContent>{unidadesNegocio?.map(u => <SelectItem key={u.id} value={u.id}><span className="flex items-center gap-2"><Building2 className="h-3 w-3" />{u.nombre}</span></SelectItem>)}</SelectContent>
                </Select>
              )}
            </div>
            {/* BLINDAJE DEFINITIVO: Selector de Sucursal ELIMINADO - Backend resuelve contexto */}
            <Button onClick={cargarDatos} disabled={loading} className="mt-5">
              {loading ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : <Clock className="h-4 w-4 mr-2" />}
              Actualizar
            </Button>
          </div>
        </CardContent>
      </Card>

      <div className="grid md:grid-cols-2 gap-4">
        {/* PAX del Día - NUEVO */}
        <Card className="border bg-gradient-to-br from-purple-50 to-white md:col-span-2">
          <CardHeader className="py-3">
            <CardTitle className="text-base flex items-center gap-2">
              <Users className="h-5 w-5 text-purple-600" /> PAX del Día (Operación en Curso)
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-3 gap-4 text-center">
              <div className="p-4 rounded-lg bg-white shadow-sm border">
                <p className="text-3xl font-bold text-purple-600">{paxHoy.toLocaleString()}</p>
                <p className="text-sm text-zinc-500 mt-1">PAX Hoy</p>
              </div>
              <div className="p-4 rounded-lg bg-white shadow-sm border">
                <p className="text-3xl font-bold text-green-600">{formatCurrency(ventasHoy)}</p>
                <p className="text-sm text-zinc-500 mt-1">Ventas Hoy</p>
              </div>
              <div className="p-4 rounded-lg bg-white shadow-sm border">
                <p className="text-3xl font-bold text-blue-600">{chequesHoy.toLocaleString()}</p>
                <p className="text-sm text-zinc-500 mt-1">Cheques Hoy</p>
              </div>
            </div>
            {fuentePaxHoy && (
              <p className="text-xs text-zinc-400 mt-3 text-center">
                Fuente: {
                  fuentePaxHoy === 'EDARSAHUB_SQL_CANONICA_DIA' ? 'EDARSAHUB SQL canónico' :
                  fuentePaxHoy === 'SIN_DATOS_CANONICOS_DIA' ? 'Sin datos canónicos del día' :
                  'Fuente no canónica'
                }
              </p>
            )}
          </CardContent>
        </Card>

        {/* Ventas por Hora */}
        <Card className="border">
          <CardHeader className="py-3">
            <CardTitle className="text-base flex items-center gap-2">
              <Clock className="h-5 w-5" /> Ventas por Hora (Horarios Pico)
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-2">
            {ventasPorHora.map((v, idx) => (
              <div key={v.hora || `hora-${idx}`} className="flex items-center gap-3">
                <span className="w-14 text-sm font-medium">{v.hora}</span>
                <div className="flex-1 h-6 bg-zinc-100 rounded overflow-hidden">
                  <div 
                    className="h-full bg-gradient-to-r from-blue-500 to-blue-600 flex items-center justify-end pr-2"
                    style={{ width: `${(v.ventas / maxVentaHora) * 100}%` }}
                  >
                    <span className="text-xs text-white font-medium">{formatCurrency(v.ventas)}</span>
                  </div>
                </div>
                <span className="w-16 text-xs text-zinc-500">{v.tickets ?? v.cheques ?? 0} tickets</span>
              </div>
            ))}
          </CardContent>
        </Card>

        {/* Ventas por Día */}
        <Card className="border">
          <CardHeader className="py-3">
            <CardTitle className="text-base flex items-center gap-2">
              <Calendar className="h-5 w-5" /> Ventas por Día de la Semana
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-2">
            {ventasPorDia.map((v, idx) => (
              <div key={v.dia || `dia-${idx}`} className="flex items-center gap-3">
                <span className="w-20 text-sm font-medium">{v.dia}</span>
                <div className="flex-1 h-6 bg-zinc-100 rounded overflow-hidden">
                  <div 
                    className="h-full bg-gradient-to-r from-green-500 to-green-600 flex items-center justify-end pr-2"
                    style={{ width: `${(v.ventas / maxVentaDia) * 100}%` }}
                  >
                    <span className="text-xs text-white font-medium">{formatCurrency(v.ventas)}</span>
                  </div>
                </div>
              </div>
            ))}
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

// ============ TAB 5: MESAS Y COMENSALES ============
function MesasComensales({ servers, unidadesNegocio, selectedUnidad, setSelectedUnidad, selectedServer, setSelectedServer, selectedSucursal, setSelectedSucursal, sucursales, showSucursalSelector, loadingUnidades }) {
  const [loading, setLoading] = useState(false);
  const [datosUnidad, setDatosUnidad] = useState(null);
  const [rotacionPorMesa, setRotacionPorMesa] = useState([]);

  const cargarDatos = async () => {
    if (!selectedServer || !selectedSucursal) return;
    setLoading(true);
    try {
      const response = await api.get(`/comercial/mesas/${selectedServer}`, {
        params: { sucursal: selectedSucursal }
      });
      setDatosUnidad(response.data.unidad);
      setRotacionPorMesa(response.data.rotacion || []);
    } catch (error) {
      logger.error('Error cargando mesas:', error);
      toast.error('Error al cargar datos de mesas');
      setDatosUnidad(null);
      setRotacionPorMesa([]);
    } finally {
      setLoading(false);
