            <div className="max-h-[300px] overflow-auto">
              <table className="w-full text-sm">
                <thead className="sticky top-0 bg-zinc-200">
                  <tr>
                    <th className="py-2 px-3 text-left">Mesa</th>
                    <th className="py-2 px-3 text-center">Capacidad</th>
                    <th className="py-2 px-3 text-center">Vueltas</th>
                    <th className="py-2 px-3 text-center">% Ocupación</th>
                  </tr>
                </thead>
                <tbody>
                  {rotacionPorMesa.map((m, idx) => (
                    <tr key={m.mesa || `mesa-${idx}`} className="border-b">
                      <td className="py-2 px-3 font-medium">{m.mesa}</td>
                      <td className="py-2 px-3 text-center">{m.capacidad} personas</td>
                      <td className="py-2 px-3 text-center font-bold">{m.vueltas}</td>
                      <td className="py-2 px-3">
                        <div className="flex items-center justify-center gap-2">
                          <Progress value={m.ocupacion} className="w-20 h-2" />
                          <span className={`text-sm ${m.ocupacion >= 80 ? 'text-green-600' : m.ocupacion >= 60 ? 'text-yellow-600' : 'text-red-600'}`}>
                            {m.ocupacion}%
                          </span>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

// ============ TAB 6: REPORTE DE PAX (Nuevo) ============
function ReportePax({ servers, unidadesNegocio, selectedUnidad, setSelectedUnidad, selectedServer, setSelectedServer, selectedSucursal, setSelectedSucursal, sucursales, showSucursalSelector, loadingUnidades }) {
  const [loading, setLoading] = useState(false);
  const [data, setData] = useState(null);
  const [viewMode, setViewMode] = useState('vendedor'); // 'vendedor' o 'ticket'
  const [expandedRows, setExpandedRows] = useState(new Set());
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [searchTerm, setSearchTerm] = useState('');
  const [sortConfig, setSortConfig] = useState({ key: 'total', direction: 'desc' });
  const [sourceStatus, setSourceStatus] = useState(null);
  const [sourceMessage, setSourceMessage] = useState('');
  const [cacheUsed, setCacheUsed] = useState(false);
  const [lastSuccessfulSync, setLastSuccessfulSync] = useState(null);

  const cargarDatos = async () => {
    if (!selectedServer || !selectedSucursal) {
      toast.error('Selecciona unidad de negocio y sucursal');
      return;
    }
    setLoading(true);
    setSourceStatus(null);
    setCacheUsed(false);
    try {
      const response = await api.get(`/comercial/reporte-pax/${selectedServer}`, {
        params: { sucursal: selectedSucursal, fecha: selectedDate, agrupacion: viewMode }
      });

      // Manejar envelope homologado
      const { source_status, source_message, cache_used, last_successful_sync, data: respData } = response.data;
      setSourceStatus(source_status || 'SUCCESS');
      setSourceMessage(source_message || '');
      setCacheUsed(cache_used || false);
      setLastSuccessfulSync(last_successful_sync || null);

      // Los datos vienen en data o directamente en response.data (backward compatible)
      setData(respData || response.data);
      setExpandedRows(new Set());
    } catch (error) {
      logger.error('Error cargando reporte PAX:', error);
      toast.error('Error al cargar reporte de PAX');
      setSourceStatus('ERROR');
      setData(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (selectedServer && selectedSucursal) {
      cargarDatos();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedServer, selectedSucursal, selectedDate, viewMode]);

  const toggleRow = (id) => {
    const newExpanded = new Set(expandedRows);
    if (newExpanded.has(id)) {
      newExpanded.delete(id);
    } else {
      newExpanded.add(id);
    }
    setExpandedRows(newExpanded);
  };

  const handleSort = (key) => {
    setSortConfig(prev => ({
      key,
      direction: prev.key === key && prev.direction === 'asc' ? 'desc' : 'asc'
    }));
  };

  // Filtrar y ordenar datos
  const filteredData = React.useMemo(() => {
    if (!data?.items) return [];
    let items = [...data.items];

    // Filtrar por búsqueda
    if (searchTerm) {
      items = items.filter(item => 
        item.nombre?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        item.folio?.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    // Ordenar
    items.sort((a, b) => {
      const aVal = a[sortConfig.key] || 0;
      const bVal = b[sortConfig.key] || 0;
      return sortConfig.direction === 'asc' ? aVal - bVal : bVal - aVal;
    });

    return items;
  }, [data, searchTerm, sortConfig]);

  const SortableHeader = ({ label, sortKey, className = '' }) => (
    <th 
      className={`py-2 px-3 cursor-pointer hover:bg-zinc-700 transition-colors ${className}`}
      onClick={() => handleSort(sortKey)}
    >
      <div className="flex items-center gap-1">
        {label}
        {sortConfig.key === sortKey && (
          sortConfig.direction === 'asc' ? <ChevronUp className="h-3 w-3" /> : <ChevronDown className="h-3 w-3" />
        )}
      </div>
    </th>
  );

  return (
    <div className="space-y-4">
      {/* Filtros - FASE 3.2: Unidad de Negocio */}
      <Card className="border">
        <CardContent className="py-4">
          <div className="flex items-center gap-4 flex-wrap">
            <div className="flex-1 min-w-[180px] max-w-xs">
              <Label className="text-xs mb-1 block">Unidad de Negocio</Label>
              {unidadesNegocio?.length === 1 ? (
                <div className="flex h-10 w-full items-center rounded-md border border-input bg-zinc-50 px-3 py-2 text-sm">
                  <Building2 className="h-4 w-4 mr-2 text-zinc-500" />{unidadesNegocio[0].nombre}
                </div>
              ) : (
                <Select value={selectedUnidad} onValueChange={setSelectedUnidad} disabled={loadingUnidades}>
                  <SelectTrigger><SelectValue placeholder={loadingUnidades ? "Cargando..." : "Seleccionar unidad"} /></SelectTrigger>
                  <SelectContent>{unidadesNegocio?.map(u => <SelectItem key={u.id} value={u.id}><span className="flex items-center gap-2"><Building2 className="h-3 w-3" />{u.nombre}</span></SelectItem>)}</SelectContent>
                </Select>
              )}
            </div>
            {/* BLINDAJE DEFINITIVO: Selector de Sucursal ELIMINADO - Backend resuelve contexto */}
            <div className="min-w-[150px]">
              <Label className="text-xs mb-1 block">Fecha</Label>
              <Input
                type="date"
                value={selectedDate}
                onChange={(e) => setSelectedDate(e.target.value)}
                className="w-full"
              />
            </div>
            <div className="min-w-[150px]">
              <Label className="text-xs mb-1 block">Agrupar por</Label>
              <Select value={viewMode} onValueChange={setViewMode}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="vendedor">
                    <div className="flex items-center gap-2">
                      <UserCheck className="h-4 w-4" /> Vendedor
                    </div>
                  </SelectItem>
                  <SelectItem value="ticket">
                    <div className="flex items-center gap-2">
                      <Receipt className="h-4 w-4" /> Cheque/Ticket
