                  </SelectItem>
                </SelectContent>
              </Select>
            </div>
            <Button onClick={cargarDatos} disabled={loading || !selectedUnidad || !selectedSucursal} className="mt-5">
              {loading ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : <RefreshCw className="h-4 w-4 mr-2" />}
              Actualizar
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* FASE 3A.4: Indicador de estado estructurado - Reporte PAX */}
      <ComercialStatusIndicator 
        status={sourceStatus} 
        message={sourceMessage} 
        meta={{ last_successful_sync: lastSuccessfulSync }}
