          requestAnimationFrame(() => setSelectedSucursal(fallback));
        }
      } else {
        // Múltiples sucursales autorizadas: mostrar selector
        setShowSucursalSelector(true);

        // Intentar restaurar sucursal guardada si está en la lista autorizada
        const savedFilters = localStorage.getItem('comercial_filters');
        if (savedFilters) {
          try {
            const filters = JSON.parse(savedFilters);
            const sucursalGuardada = sucursalesRBAC.find(s => 
              (s.id || s.codigo || s.nombre) === filters.sucursal
            );
            if (sucursalGuardada) {
              const valor = sucursalGuardada.id || sucursalGuardada.codigo || sucursalGuardada.nombre;
              logger.log(`[Comercial RBAC] Restaurando sucursal guardada: ${valor}`);
              requestAnimationFrame(() => setSelectedSucursal(valor));
            }
          } catch (e) {}
        }
      }
    } else if (!selectedUnidad) {
      // Sin unidad seleccionada: limpiar estado
      setSucursales([]);
      setShowSucursalSelector(false);
      setSelectedSucursal('');
    }
  }, [selectedUnidad, unidadesNegocio]);

